$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$response=Invoke-WebRequest -UseBasicParsing http://192.168.122.1:8872/m78-build-intermediates.json;$manifest=$response.Content|ConvertFrom-Json;$rows=@()
